      "trueLabel": {"type": "string"},
      "falseLabel": {"type": "string"}
    },
    "required": ["expression"]
  },
  "outputDefinition": {
    "matchedCase": {"type": "string","description": "The label of the matched branch (true/false label)","var": "matchedCase"},
    "matchedCaseId": {"type": "string","description": "The branch that was taken (true or false)","var": "matchedCaseId"}
  },
  "inputDefaults": {"trueLabel": "True","falseLabel": "False"},
  "form": {
    "id": "decision-properties","title": "Decision configuration",
    "sections": [{"id": "condition","title": "Condition","fields": [
      {"name": "inputs.expression","type": "custom","component": "script-editor",
       "componentProps": {"language": "javascript","returnType": "boolean","validationMode": "expression","minHeight": 100},
       "label": "Expression","description": "JavaScript expression that evaluates to true or false"},
      {"name": "inputs.trueLabel","type": "text","label": "True branch label"},
      {"name": "inputs.falseLabel","type": "text","label": "False branch label"}
    ]}]
  }
}

# --- Script node definition ---
script_def = {
  "nodeType": "core.action.script",
  "version": "1.0",
  "category": "data-operations",
  "description": "Run custom JavaScript code",
  "tags": ["code","javascript","python"],
  "sortOrder": 35,
  "supportsErrorHandling": True,
  "display": {"label": "Script","icon": "code"},
  "handleConfiguration": [
    {"position": "left","handles": [{"id": "input","type": "target","handleType": "input"}]},
    {"position": "right","handles": [
      {"id": "success","type": "source","handleType": "output"},
      {"id": "error","label": "Error","type": "source","handleType": "output","visible": "{inputs.errorHandlingEnabled}","constraints": {"maxConnections": 1}}
    ]}
  ],
  "debug": {"runtime": "clientScript"},
  "model": {"type": "bpmn:ScriptTask"},
  "inputDefinition": {
    "type": "object",
    "properties": {"script": {"type": "string","minLength": 1,"errorMessage": "A script function is required","validationSeverity": "warning"}},
    "required": ["script"]
  },
  "inputDefaults": {"script": ""},
  "outputDefinition": {
    "output": {"type": "object","description": "The return value of the script","source": "=result.response","var": "output"},
    "error": {"type": "object","description": "Error information if the node fails","source": "=Error","var": "error",
      "schema": {"$schema":"http://json-schema.org/draft-07/schema#","type":"object",
        "required":["code","message","detail","category","status"],
        "properties":{"code":{"type":"string"},"message":{"type":"string"},"detail":{"type":"string"},"category":{"type":"string"},"status":{"type":"integer"}},
        "additionalProperties": False}}
  }
}

# --- End node definition ---
end_def = {
  "nodeType": "core.control.end",
  "version": "1.0",
  "category": "control-flow",
  "description": "Mark the end of a workflow path",
  "tags": ["control-flow","end","finish","complete"],
  "sortOrder": 20,
  "display": {"label": "End","icon": "circle-check","shape": "circle"},
  "handleConfiguration": [
    {"position": "left","handles": [{"id": "input","type": "target","handleType": "input"}]}
  ],
  "model": {"type": "bpmn:EndEvent"},
  "runtimeConstraints": {"exclude": ["api-function"]}
}

# The IxP outputDefinition (verbatim from registry)
ixp_out_def = ixp_def['outputDefinition']
# Script outputDefinition
script_out_def = script_def['outputDefinition']

# IxP node ID
IXP_ID = "extractInvoice"
IXP_NODE_TYPE = ixp_def['nodeType']
IXP_VERSION = ixp_def['version']

# --- Build the complete flow ---
flow = {
  "id": scaffold['id'],
  "version": scaffold['version'],
  "name": scaffold['name'],
  "variables": {
    "globals": [
      {
        "id": "invoiceFile",
        "name": "invoiceFile",
        "type": "file",
        "direction": "in"
      }
    ],
    "nodes": []
  },
  "nodes": [
    # 1. Manual trigger (from scaffold)
    scaffold['nodes'][0],
    # 2. IxP extraction node
    {
      "id": IXP_ID,
      "type": IXP_NODE_TYPE,
      "typeVersion": IXP_VERSION,
      "display": {"label": "Extract Invoice Fields"},
      "inputs": {
        "model": {
          "id": ixp_def['inputDefaults']['model']['id'],
          "modelName": ixp_def['inputDefaults']['model']['modelName'],
          "modelDisplayName": ixp_def['inputDefaults']['model']['modelDisplayName'],
          "folderKey": ixp_def['inputDefaults']['model']['folderKey'],
          "folderName": ixp_def['inputDefaults']['model']['folderName'],
          "folderPath": ixp_def['inputDefaults']['model']['folderPath'],
          "description": ixp_def['inputDefaults']['model']['description']
        },
        "modelName": ixp_def['inputDefaults']['modelName'],
        "description": ixp_def['inputDefaults']['description'],
        "projectName": ixp_def['inputDefaults']['projectName'],
        "versionTag": "",
        "folderKey": ixp_def['inputDefaults']['folderKey'],
        "folderName": ixp_def['inputDefaults']['folderName'],
        "fileRef": "=js:$vars.invoiceFile",
